using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class FixHud06AReferences{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var v=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>();v.Legacy=v.Railway.Panel.GetComponent<CanvasGroup>();if(v.Legacy==null)v.Legacy=v.Railway.Panel.AddComponent<CanvasGroup>();CanvasGroup Group(GameObject go){var g=go.GetComponent<CanvasGroup>();if(g==null)g=go.AddComponent<CanvasGroup>();return g;}
v.QuietPanels=new[]{Group(h.Layout.Notifications.gameObject),Group(h.Layout.SelectionPanel.gameObject),Group(h.Sections.Single(s=>s.Id=="first-loop").Body)};v.ResourcePanel=Group(h.Layout.ResourcePanel.gameObject);
foreach(var b in v.Root.GetComponentsInChildren<UnityEngine.UI.Button>(true)){var t=b.GetComponentInChildren<TMPro.TMP_Text>(true);t.rectTransform.offsetMin=new Vector2(6,2);t.rectTransform.offsetMax=new Vector2(-6,-2);if(!v.Rows.Contains(b))t.textWrappingMode=TMPro.TextWrappingModes.NoWrap;}
EditorUtility.SetDirty(v);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Saved missing legacy CanvasGroup references";}}
